CREATE TABLE accounts (
    id INT PRIMARY KEY,
    email VARCHAR(100) NOT NULL UNIQUE,
    balance NUMERIC(12,2) NOT NULL CHECK (balance >= 0),
    status VARCHAR(20) NOT NULL CHECK (status IN ('active', 'suspended', 'closed'))
);

INSERT INTO accounts VALUES (1, 'user@example.com', 100.50, 'active');
SELECT email, balance, status FROM accounts;

CREATE TABLE customers (
    id INT PRIMARY KEY,
    name VARCHAR(50) NOT NULL
);
CREATE TABLE customer_orders (
    order_id INT PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    amount NUMERIC(10,2) NOT NULL
);

INSERT INTO customers VALUES (1, 'Alice');
INSERT INTO customer_orders VALUES (101, 1, 250.00);

-- Deleting Alice cascades and deletes order 101 automatically
DELETE FROM customers WHERE id = 1;
SELECT COUNT(*) AS remaining_orders FROM customer_orders;

-- 3NF Design: Normalized Departments and Employees
CREATE TABLE departments (
    dept_id INT PRIMARY KEY,
    dept_name VARCHAR(50) NOT NULL UNIQUE
);
CREATE TABLE company_staff (
    emp_id INT PRIMARY KEY,
    emp_name VARCHAR(50) NOT NULL,
    dept_id INT NOT NULL REFERENCES departments(dept_id)
);

INSERT INTO departments VALUES (10, 'Engineering');
INSERT INTO company_staff VALUES (1, 'Maya', 10);

SELECT e.emp_name, d.dept_name
FROM company_staff e
JOIN departments d ON e.dept_id = d.dept_id;

-- Denormalized order summary caching customer_name directly for fast reads
CREATE TABLE fast_orders (
    order_id INT PRIMARY KEY,
    customer_id INT NOT NULL,
    cached_customer_name VARCHAR(50) NOT NULL,
    order_total NUMERIC(10,2) NOT NULL
);
INSERT INTO fast_orders VALUES (1, 101, 'Alice', 150.00);
SELECT order_id, cached_customer_name, order_total FROM fast_orders;
